#define main block_auth_embedded_main
#include "block_auth.cpp"
#undef main

#include <sstream>

struct BNode{std::vector<float>c;float radius=0,qerr=0;std::vector<uint8_t>qcode;int begin=0,end=0,left=-1,right=-1;bool leaf()const{return left<0;}};
struct BTree{std::vector<int>ids;std::vector<BNode>nodes;};
class BatchForest{
 const Matrix&x_;const SQ4&sq_;int leaf_;
 int build(BTree&t,int begin,int end){int d=x_.d,n=end-begin;BNode v;v.begin=begin;v.end=end;v.c.assign(d,0);std::vector<double>s2(d);for(int p=begin;p<end;++p)for(int j=0;j<d;++j){float z=x_[t.ids[p]][j];v.c[j]+=z;s2[j]+=z*z;}for(float&z:v.c)z/=n;int sd=0;double bv=-1;for(int j=0;j<d;++j){double z=s2[j]/n-v.c[j]*v.c[j];if(z>bv){bv=z;sd=j;}}float r2=0;for(int p=begin;p<end;++p)r2=std::max(r2,l2(x_[t.ids[p]],v.c.data(),d));v.radius=std::nextafter(std::sqrt(r2)*(1+1e-6f)+1e-5f,std::numeric_limits<float>::infinity());v.qcode.resize(d);float e2=0;for(int j=0;j<d;++j){int q=sq_.step[j]?std::clamp((int)std::lround((v.c[j]-sq_.lo[j])/sq_.step[j]),0,15):0;v.qcode[j]=q;float z=v.c[j]-(sq_.lo[j]+q*sq_.step[j]);e2+=z*z;}v.qerr=std::nextafter(std::sqrt(e2)*(1+1e-6f)+1e-5f,std::numeric_limits<float>::infinity());int me=t.nodes.size();t.nodes.push_back(std::move(v));if(n<=leaf_)return me;int mid=begin+n/2;std::nth_element(t.ids.begin()+begin,t.ids.begin()+mid,t.ids.begin()+end,[&](int a,int b){float x=x_[a][sd],y=x_[b][sd];return x<y||(x==y&&a<b);});int l=build(t,begin,mid),r=build(t,mid,end);t.nodes[me].left=l;t.nodes[me].right=r;return me;}
public:std::vector<BTree>trees;BatchForest(const Matrix&x,const SQ4&sq,const std::vector<std::vector<int>>&ls,int leaf):x_(x),sq_(sq),leaf_(leaf),trees(ls.size()){for(size_t i=0;i<ls.size();++i){trees[i].ids=ls[i];if(!ls[i].empty())build(trees[i],0,ls[i].size());}}
};
static float qcenter_lb(const float*q,const BNode&n,const SQ4&sq){float s=0;for(int j=0;j<sq.d;++j){float c=sq.lo[j]+n.qcode[j]*sq.step[j],z=q[j]-c;s+=z*z;}return std::max(0.0f,std::sqrt(s)-n.qerr-n.radius);}
struct BStats{uint64_t nodes=0,opened=0,frontier=0,pruned=0,exact=0;double sq_node_bytes=0,exact_node_bytes=0;};
static BStats traverse(const BTree&t,const SQ4&sq,const float*q,float tau){BStats s;if(t.nodes.empty())return s;std::vector<int>st{0};while(!st.empty()){const BNode&n=t.nodes[st.back()];st.pop_back();++s.nodes;s.sq_node_bytes+=n.leaf()?108:140;s.exact_node_bytes+=n.leaf()?552:584;if(qcenter_lb(q,n,sq)>tau){++s.frontier;s.pruned+=n.end-n.begin;continue;}if(n.leaf()){s.opened+=n.end-n.begin;for(int p=n.begin;p<n.end;++p)if(sq.lb(q,t.ids[p])<=tau)++s.exact;}else{st.push_back(n.left);st.push_back(n.right);}}return s;}
static BStats direct_blocks(const BTree&t,const SQ4&sq,const float*q,float tau){BStats s;for(const BNode&n:t.nodes)if(n.leaf()){++s.nodes;s.sq_node_bytes+=108;if(qcenter_lb(q,n,sq)>tau){++s.frontier;s.pruned+=n.end-n.begin;}else{s.opened+=n.end-n.begin;for(int p=n.begin;p<n.end;++p)if(sq.lb(q,t.ids[p])<=tau)++s.exact;}}return s;}
struct BCfg{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="batch_pruning_results.csv";int base=100000,nq=50,k=100;std::vector<int>probes{8,16,32,64,100},leaves{16,32,64,128,256};};
static std::vector<int>bints(const std::string&s){std::vector<int>v;std::stringstream ss(s);std::string z;while(std::getline(ss,z,','))v.push_back(std::stoi(z));return v;}
static BCfg bparse(int ac,char**av){BCfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--nprobes")c.probes=bints(v());else if(a=="--leaf-sizes")c.leaves=bints(v());else if(a=="--help"){std::cout<<"Usage: batch_pruning_experiment [--base 100000] [--queries 50] [--leaf-sizes 16,32,64,128,256]\n";std::exit(0);}else throw std::runtime_error("unknown option "+a);}return c;}
static std::vector<std::vector<int>>prefix_lists(const std::string&p,size_t n){std::ifstream f(p);if(!f)throw std::runtime_error("cannot open assignments");std::vector<std::vector<int>>ls(100);long id,c;size_t z=0;while(f>>id>>c)if(id>=0&&(size_t)id<n){ls[c].push_back(id);++z;}if(z!=n)throw std::runtime_error("assignment prefix mismatch");return ls;}
#ifndef BATCH_PRUNING_NO_MAIN
int main(int ac,char**av)try{BCfg cfg=bparse(ac,av);Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.nq);auto ls=prefix_lists(cfg.assign,xb.rows());auto cs=centers(xb,ls);std::cerr<<"Building per-object SQ4 certificates...\n";SQ4 sq(xb);struct Q{std::vector<int>clusters;float tau;uint64_t visited=0,flat_exact=0;};std::vector<std::vector<Q>>qs(cfg.probes.size(),std::vector<Q>(xq.rows()));
for(size_t pi=0;pi<cfg.probes.size();++pi){int np=cfg.probes[pi];for(size_t qi=0;qi<xq.rows();++qi){Q&q=qs[pi][qi];std::vector<int>pr(100);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){float x=l2(xq[qi],cs[a].data(),xb.d),y=l2(xq[qi],cs[b].data(),xb.d);return x<y||(x==y&&a<b);});q.clusters.assign(pr.begin(),pr.begin()+np);std::priority_queue<std::pair<float,int>>top;for(int c:q.clusters)for(int id:ls[c]){float d=l2(xq[qi],xb[id],xb.d);++q.visited;if((int)top.size()<cfg.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}q.tau=std::sqrt(top.top().first);for(int c:q.clusters)for(int id:ls[c])q.flat_exact+=sq.lb(xq[qi],id)<=q.tau;}}
std::ofstream out(cfg.out);out<<"base,k,nprobe,leaf_size,avg_scanned,avg_tree_nodes,avg_frontier,avg_pruned,point_prune_ratio,avg_opened_records,avg_exact_open,flat_sq4_bytes,batch_sq4center_bytes,batch_exactcenter_bytes,reduction_sq4center,reduction_exactcenter,direct_block_count,direct_prune_ratio,direct_block_bytes,direct_block_reduction\n";std::cout<<"nprobe leaf tree_prune tree_reduction direct_prune direct_reduction\n";
for(int leaf:cfg.leaves){std::cerr<<"Building authenticated batch trees, leaf="<<leaf<<"...\n";BatchForest forest(xb,sq,ls,leaf);for(size_t pi=0;pi<cfg.probes.size();++pi){uint64_t vis=0,flat_exact=0,nodes=0,frontier=0,pruned=0,opened=0,exact=0,dblocks=0,dpruned=0,dopened=0,dexact=0;double sqnodes=0,exnodes=0,dnodebytes=0;for(size_t qi=0;qi<xq.rows();++qi){const Q&q=qs[pi][qi];vis+=q.visited;flat_exact+=q.flat_exact;for(int c:q.clusters){BStats s=traverse(forest.trees[c],sq,xq[qi],q.tau),d=direct_blocks(forest.trees[c],sq,xq[qi],q.tau);nodes+=s.nodes;frontier+=s.frontier;pruned+=s.pruned;opened+=s.opened;exact+=s.exact;sqnodes+=s.sq_node_bytes;exnodes+=s.exact_node_bytes;dblocks+=d.nodes;dpruned+=d.pruned;dopened+=d.opened;dexact+=d.exact;dnodebytes+=d.sq_node_bytes;}}double nq=xq.rows(),flat=vis*72.0/nq+flat_exact*512.0/nq,bsq=sqnodes/nq+opened*72.0/nq+exact*512.0/nq,bex=exnodes/nq+opened*72.0/nq+exact*512.0/nq,dbytes=dnodebytes/nq+dopened*72.0/nq+dexact*512.0/nq;out<<xb.rows()<<','<<cfg.k<<','<<cfg.probes[pi]<<','<<leaf<<','<<vis/nq<<','<<nodes/nq<<','<<frontier/nq<<','<<pruned/nq<<','<<pruned/(double)vis<<','<<opened/nq<<','<<exact/nq<<','<<flat<<','<<bsq<<','<<bex<<','<<1-bsq/flat<<','<<1-bex/flat<<','<<dblocks/nq<<','<<dpruned/(double)vis<<','<<dbytes<<','<<1-dbytes/flat<<'\n';std::cout<<std::setw(6)<<cfg.probes[pi]<<' '<<std::setw(4)<<leaf<<' '<<std::fixed<<std::setprecision(4)<<pruned/(double)vis<<' '<<1-bsq/flat<<' '<<dpruned/(double)vis<<' '<<1-dbytes/flat<<'\n';}}
std::cerr<<"Wrote "<<cfg.out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
#endif
